<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require dirname(__DIR__,2).'/vendor/autoload.php';use App\Admin;use App\Security;
Admin::requirePermission('products.manage');$pdo=db();$id=(int)($_GET['id']??$_POST['product_id']??0);$q=$pdo->prepare("SELECT id,name FROM products WHERE id=?");$q->execute([$id]);$product=$q->fetch();if(!$product){http_response_code(404);exit('المنتج غير موجود.');}$error='';
function vipDeleteProductImage(?string $path):void{$root=realpath(dirname(__DIR__).'/uploads/products');$file=$path?realpath(dirname(__DIR__).'/'.$path):false;if($root&&$file&&str_starts_with($file,$root.DIRECTORY_SEPARATOR)&&is_file($file))@unlink($file);}
if($_SERVER['REQUEST_METHOD']==='POST'){Security::requireCsrf();try{$action=(string)($_POST['action']??'');$imageId=(int)($_POST['image_id']??0);$q=$pdo->prepare("SELECT * FROM product_images WHERE id=? AND product_id=?");$q->execute([$imageId,$id]);$img=$imageId?$q->fetch():null;
if($action==='upload'){$files=$_FILES['images']??null;if(!$files||!is_array($files['name']??null))throw new RuntimeException('اختر صورة واحدة على الأقل.');$has=(int)$pdo->query("SELECT COUNT(*) FROM product_images WHERE product_id=".(int)$id." AND is_primary=1")->fetchColumn()>0;$added=0;foreach($files['name'] as $i=>$name){if(($files['error'][$i]??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;$file=['name'=>$name,'type'=>$files['type'][$i]??'','tmp_name'=>$files['tmp_name'][$i]??'','error'=>$files['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$files['size'][$i]??0];$path=Admin::uploadImage($file,'products');$pdo->prepare("INSERT INTO product_images(product_id,image_path,alt_text,is_primary,sort_order) VALUES(?,?,?,?,?)")->execute([$id,$path,$product['name'],(!$has&&$added===0)?1:0,(int)$pdo->query("SELECT COALESCE(MAX(sort_order),0)+1 FROM product_images WHERE product_id=".(int)$id)->fetchColumn()]);$added++;}if(!$added)throw new RuntimeException('لم يتم اختيار صورة صالحة.');}
elseif(!$img)throw new RuntimeException('الصورة غير موجودة.');
elseif($action==='primary'){$pdo->beginTransaction();$pdo->prepare("UPDATE product_images SET is_primary=0 WHERE product_id=?")->execute([$id]);$pdo->prepare("UPDATE product_images SET is_primary=1 WHERE id=?")->execute([$imageId]);$pdo->commit();}
elseif($action==='replace'){$file=$_FILES['image']??[];$new=Admin::uploadImage($file,'products');$pdo->prepare("UPDATE product_images SET image_path=? WHERE id=?")->execute([$new,$imageId]);vipDeleteProductImage($img['image_path']);}
elseif($action==='delete'){$pdo->beginTransaction();$pdo->prepare("DELETE FROM product_images WHERE id=?")->execute([$imageId]);if((int)$img['is_primary']){$q=$pdo->prepare("SELECT id FROM product_images WHERE product_id=? ORDER BY sort_order,id LIMIT 1");$q->execute([$id]);$next=$q->fetchColumn();if($next)$pdo->prepare("UPDATE product_images SET is_primary=1 WHERE id=?")->execute([$next]);}$pdo->commit();vipDeleteProductImage($img['image_path']);}
elseif($action==='move'){$direction=(int)($_POST['direction']??0);$q=$pdo->prepare("SELECT id,sort_order FROM product_images WHERE product_id=? ORDER BY sort_order,id");$q->execute([$id]);$list=$q->fetchAll();$index=array_search($imageId,array_column($list,'id'));$target=$index===false?$index:$index+$direction;if($target!==false&&isset($list[$target])&&$index!==false){$pdo->beginTransaction();$pdo->prepare("UPDATE product_images SET sort_order=? WHERE id=?")->execute([$list[$index]['sort_order'],$list[$target]['id']]);$pdo->prepare("UPDATE product_images SET sort_order=? WHERE id=?")->execute([$list[$target]['sort_order'],$imageId]);$pdo->commit();}}
else throw new RuntimeException('إجراء غير معروف.');
Admin::audit('product.image.'.$action,'product',$id,['image_id'=>$imageId]);header('Location: product-images.php?id='.$id.'&updated=1');exit;
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'تعذر تعديل الصور. تحقق من صيغة الصورة وحجمها.';}}
$q=$pdo->prepare("SELECT * FROM product_images WHERE product_id=? ORDER BY is_primary DESC,sort_order,id");$q->execute([$id]);$images=$q->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>صور المنتج | VIP 27</title><link rel="stylesheet" href="../assets/css/store.css"><style>.wrap{max-width:1100px;margin:28px auto;padding:0 16px}.gallery{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.tile,.upload{border:1px solid #49371c;background:#111;border-radius:12px;padding:12px}.tile img{width:100%;height:165px;object-fit:contain;background:#090909}.tile form{margin-top:7px}.tile .btn{width:100%;margin-top:4px}.upload input{max-width:100%;color:#fff}@media(max-width:700px){.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}}</style></head><body><main class="wrap"><a class="text-link" href="products.php">← المنتجات</a><h1>معرض صور: <?=e($product['name'])?></h1><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['updated'])):?><div class="notice">تم تحديث معرض الصور.</div><?php endif;?><section class="upload"><h2>إضافة صور جديدة</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="action" value="upload"><input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple required><button class="btn btn-gold">رفع الصور</button></form></section><div class="gallery"><?php foreach($images as $img):?><article class="tile"><img src="../<?=e($img['image_path'])?>" alt="<?=e($img['alt_text']??$product['name'])?>"><?php if((int)$img['is_primary']):?><span class="available">الصورة الرئيسية</span><?php endif;?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="image_id" value="<?=(int)$img['id']?>"><button class="btn btn-outline" name="action" value="primary">تعيين كرئيسية</button><button class="btn btn-outline" name="action" value="move" value="move" onclick="this.form.direction.value='-1'">تحريك لأعلى</button><input type="hidden" name="direction" value="-1"><button class="btn btn-outline" name="action" value="delete" onclick="return confirm('حذف الصورة؟')">حذف الصورة</button></form><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=e(Security::csrfToken())?>"><input type="hidden" name="product_id" value="<?=$id?>"><input type="hidden" name="image_id" value="<?=(int)$img['id']?>"><input type="hidden" name="action" value="replace"><input type="file" name="image" accept="image/jpeg,image/png,image/webp" required><button class="btn btn-outline">استبدال الصورة</button></form></article><?php endforeach;?></div><?php if(!$images):?><div class="empty-state">لا توجد صور لهذا المنتج.</div><?php endif;?></main></body></html>